mapper.update:
UPDATE outbox_event
SET status = 1,
    next_retry_time = DATE_ADD(NOW(), INTERVAL #{waitTime} SECOND)
WHERE id = #{id}
  AND (
    (
        status = 0
        AND (next_retry_time IS NULL OR next_retry_time <= NOW())
    ) OR (
        status = 1
        AND next_retry_time <= NOW()
    )
  )

UPDATE outbox_event
SET status = 0,
    retry_count = retry_count + 1,
    next_retry_time = #{nextRetryTime}
WHERE id = #{id}
  AND status = 1

mapper.delete:
DELETE FROM outbox_event
WHERE status = 2
  AND published_time < #{before}
ORDER BY published_time ASC
LIMIT #{limit}
